"""
test_solution.py — unittest suite for solution.evaluate(text).

Encodes the table from SPEC_CASES.md (rows 1-124) plus extra edge cases
called out as "traps" in the task brief (maximal munch, negative-exponent
evaluation-time check, float propagation, deep nesting, non-str input).

Run with:  python3 test_solution.py
"""

import math
import sys
import unittest

from solution import evaluate


class ValueCasesMixin:
    """Helper for asserting a value result with an exact type check."""

    def assert_value(self, text, expected, expected_type):
        result = evaluate(text)
        self.assertIsInstance(
            result, expected_type,
            f"evaluate({text!r}) = {result!r} ({type(result).__name__}), "
            f"expected type {expected_type.__name__}",
        )
        # bool is a subclass of int; the grammar never produces bool, but
        # guard against it anyway to be precise about "int" meaning int.
        self.assertNotIsInstance(result, bool)
        if expected_type is float:
            self.assertTrue(math.isclose(result, expected, rel_tol=1e-12) or result == expected)
        else:
            self.assertEqual(result, expected)


# ---------------------------------------------------------------------------
# A. Literals & whitespace
# ---------------------------------------------------------------------------
class TestLiteralsWhitespace(ValueCasesMixin, unittest.TestCase):
    def test_01_simple_int(self):
        self.assert_value("42", 42, int)

    def test_02_zero(self):
        self.assert_value("0", 0, int)

    def test_03_leading_zeros(self):
        self.assert_value("007", 7, int)

    def test_04_surrounding_spaces(self):
        self.assert_value("  42  ", 42, int)

    def test_05_tab_newline(self):
        self.assert_value("\t5\n", 5, int)

    def test_06_all_whitespace_kinds(self):
        self.assert_value("\r\f\v 9 \v\f\r", 9, int)

    def test_07_empty_input(self):
        with self.assertRaises(ValueError):
            evaluate("")

    def test_08_whitespace_only(self):
        with self.assertRaises(ValueError):
            evaluate("   ")

    def test_09_long_digit_run(self):
        self.assert_value("9" * 300, int("9" * 300), int)

    def test_10_underscore_rejected(self):
        with self.assertRaises(ValueError):
            evaluate("1_000")


# ---------------------------------------------------------------------------
# B. Unicode / unknown-character lexical errors
# ---------------------------------------------------------------------------
class TestUnknownChars(unittest.TestCase):
    def test_11_arabic_indic_digit(self):
        with self.assertRaises(ValueError):
            evaluate("\u0663")

    def test_12_dollar(self):
        with self.assertRaises(ValueError):
            evaluate("2 $ 3")

    def test_13_at_sign(self):
        with self.assertRaises(ValueError):
            evaluate("2 @ 3")

    def test_14_caret(self):
        with self.assertRaises(ValueError):
            evaluate("2^3")

    def test_15_dot_in_float_literal(self):
        with self.assertRaises(ValueError):
            evaluate("1.5 + 1")

    def test_16_trailing_dot(self):
        with self.assertRaises(ValueError):
            evaluate("1.")

    def test_17_leading_dot(self):
        with self.assertRaises(ValueError):
            evaluate(".5")

    def test_18_scientific_notation(self):
        with self.assertRaises(ValueError):
            evaluate("2e3")


# ---------------------------------------------------------------------------
# C. Operator tokenizer maximal munch
# ---------------------------------------------------------------------------
class TestMaximalMunch(ValueCasesMixin, unittest.TestCase):
    def test_19_floordiv(self):
        self.assert_value("2 // 3", 0, int)

    def test_20_triple_slash(self):
        with self.assertRaises(ValueError):
            evaluate("2 /// 3")

    def test_21_star(self):
        self.assert_value("2 * 3", 6, int)

    def test_22_dstar(self):
        self.assert_value("2 ** 3", 8, int)

    def test_23_triple_star(self):
        with self.assertRaises(ValueError):
            evaluate("2 *** 3")

    def test_24_quad_star(self):
        with self.assertRaises(ValueError):
            evaluate("2 **** 3")

    def test_25_quintuple_slash(self):
        with self.assertRaises(ValueError):
            evaluate("2 ///// 3")


# ---------------------------------------------------------------------------
# D. Precedence & associativity
# ---------------------------------------------------------------------------
class TestPrecedenceAssociativity(ValueCasesMixin, unittest.TestCase):
    def test_26(self):
        self.assert_value("2+3*4", 14, int)

    def test_27(self):
        self.assert_value("(2+3)*4", 20, int)

    def test_28(self):
        self.assert_value("2*3+4", 10, int)

    def test_29(self):
        self.assert_value("2-3-4", -5, int)

    def test_30(self):
        self.assert_value("20/4/5", 1.0, float)

    def test_31(self):
        self.assert_value("20//4//5", 1, int)

    def test_32(self):
        self.assert_value("2**3**2", 512, int)

    def test_33(self):
        self.assert_value("2**2**3", 256, int)

    def test_34(self):
        self.assert_value("2**3*2", 16, int)

    def test_35(self):
        self.assert_value("2*3**2", 18, int)

    def test_36(self):
        self.assert_value("-2**2", -4, int)

    def test_37(self):
        self.assert_value("(-2)**2", 4, int)

    def test_38(self):
        self.assert_value("-2**2**2", -16, int)

    def test_39(self):
        self.assert_value("2+3*4**2", 50, int)

    def test_40(self):
        self.assert_value("(2+3)*4**2", 80, int)


# ---------------------------------------------------------------------------
# E. Unary chains
# ---------------------------------------------------------------------------
class TestUnaryChains(ValueCasesMixin, unittest.TestCase):
    def test_41(self):
        self.assert_value("--3", 3, int)

    def test_42(self):
        self.assert_value("+-+-3", 3, int)

    def test_43(self):
        self.assert_value("3 - - - 2", 1, int)

    def test_44(self):
        self.assert_value("2 - -2", 4, int)

    def test_45(self):
        self.assert_value("-(3+4)", -7, int)

    def test_46(self):
        self.assert_value("-(-(-5))", -5, int)

    def test_47(self):
        self.assert_value("----5", 5, int)

    def test_48(self):
        self.assert_value("-----5", -5, int)

    def test_49(self):
        self.assert_value("+ + + 5", 5, int)

    def test_50(self):
        self.assert_value("- -5", 5, int)


# ---------------------------------------------------------------------------
# F. `**` combined with unary / negative-exponent trap
# ---------------------------------------------------------------------------
class TestNegativeExponentTrap(ValueCasesMixin, unittest.TestCase):
    def test_51(self):
        with self.assertRaises(ValueError):
            evaluate("2**-1")

    def test_52(self):
        with self.assertRaises(ValueError):
            evaluate("2**(1-3)")

    def test_53(self):
        with self.assertRaises(ValueError):
            evaluate("2**-3**2")

    def test_54(self):
        with self.assertRaises(ValueError):
            evaluate("-2**-3**2")

    def test_55(self):
        self.assert_value("0**0", 1, int)

    def test_56(self):
        self.assert_value("0**5", 0, int)

    def test_57_zero_base_negative_exp_must_be_valueerror(self):
        # The single riskiest trap: must NOT be ZeroDivisionError.
        with self.assertRaises(ValueError):
            evaluate("0**-1")

    def test_58(self):
        with self.assertRaises(ValueError):
            evaluate("0**-5")

    def test_59(self):
        with self.assertRaises(ValueError):
            evaluate("(0-0)**-1")

    def test_60(self):
        self.assert_value("-2**0", -1, int)


# ---------------------------------------------------------------------------
# G. Division / floordiv / modulo sign semantics
# ---------------------------------------------------------------------------
class TestDivModSigns(ValueCasesMixin, unittest.TestCase):
    def test_61(self):
        self.assert_value("-7 // 2", -4, int)

    def test_62(self):
        self.assert_value("7 // -2", -4, int)

    def test_63(self):
        self.assert_value("-7 // -2", 3, int)

    def test_64(self):
        self.assert_value("-7 % 2", 1, int)

    def test_65(self):
        self.assert_value("7 % -2", -1, int)

    def test_66(self):
        self.assert_value("-7 % -2", -1, int)

    def test_67(self):
        self.assert_value("10 % 3", 1, int)

    def test_68(self):
        self.assert_value("-10 % 3", 2, int)

    def test_69(self):
        self.assert_value("10 % -3", -2, int)

    def test_70(self):
        self.assert_value("-10 % -3", -1, int)


# ---------------------------------------------------------------------------
# H. Float propagation
# ---------------------------------------------------------------------------
class TestFloatPropagation(ValueCasesMixin, unittest.TestCase):
    def test_71(self):
        self.assert_value("8/2", 4.0, float)

    def test_72(self):
        self.assert_value("8/2*2", 8.0, float)

    def test_73(self):
        self.assert_value("1/2+1", 1.5, float)

    def test_74(self):
        self.assert_value("(8/2)//3", 1.0, float)

    def test_75(self):
        self.assert_value("(8/2)%3", 1.0, float)

    def test_76(self):
        self.assert_value("(8/2)**2", 16.0, float)

    def test_77(self):
        self.assert_value("(8/2)**0", 1.0, float)

    def test_78(self):
        self.assert_value("4/2", 2.0, float)

    def test_79(self):
        self.assert_value("1/4*4", 1.0, float)

    def test_80(self):
        self.assert_value("3+4/2", 5.0, float)


# ---------------------------------------------------------------------------
# I. ZeroDivisionError cases
# ---------------------------------------------------------------------------
class TestZeroDivisionErrors(ValueCasesMixin, unittest.TestCase):
    def test_81(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("1/0")

    def test_82(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("1//0")

    def test_83(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("1%0")

    def test_84(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("(1/1)/0")

    def test_85(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("(1/1)//0")

    def test_86(self):
        with self.assertRaises(ZeroDivisionError):
            evaluate("(1/1)%0")

    def test_87(self):
        self.assert_value("0/1", 0.0, float)

    def test_88a(self):
        self.assert_value("0//1", 0, int)

    def test_88b(self):
        self.assert_value("0%1", 0, int)

    def test_zde_not_valueerror_subclass(self):
        self.assertFalse(issubclass(ZeroDivisionError, ValueError))
        with self.assertRaises(ZeroDivisionError):
            try:
                evaluate("1/0")
            except ValueError:
                self.fail("ZeroDivisionError must not be caught as ValueError")

    def test_leftmost_error_wins(self):
        # 1/0 evaluated (leftmost/depth-first) before 2**-1 is reached.
        with self.assertRaises(ZeroDivisionError):
            evaluate("1/0 + 2**-1")


# ---------------------------------------------------------------------------
# J. Parentheses
# ---------------------------------------------------------------------------
class TestParentheses(ValueCasesMixin, unittest.TestCase):
    def test_89_empty_parens(self):
        with self.assertRaises(ValueError):
            evaluate("()")

    def test_90_missing_close(self):
        with self.assertRaises(ValueError):
            evaluate("(1+2")

    def test_91_unmatched_trailing_close(self):
        with self.assertRaises(ValueError):
            evaluate("1+2)")

    def test_92_extra_trailing_close(self):
        with self.assertRaises(ValueError):
            evaluate("(1))")

    def test_93_missing_one_close(self):
        with self.assertRaises(ValueError):
            evaluate("((1)")

    def test_94_balanced_nesting(self):
        self.assert_value("((1))", 1, int)

    def test_95_adjacent_primaries(self):
        with self.assertRaises(ValueError):
            evaluate("(1)(2)")

    def test_96(self):
        self.assert_value("(-5)", -5, int)

    def test_97(self):
        self.assert_value("-(5)", -5, int)

    def test_98(self):
        self.assert_value("(((((1)))))", 1, int)


# ---------------------------------------------------------------------------
# K. Adjacent operands / missing operand / stray operator
# ---------------------------------------------------------------------------
class TestAdjacentMissingStray(ValueCasesMixin, unittest.TestCase):
    def test_99(self):
        with self.assertRaises(ValueError):
            evaluate("2 3")

    def test_100(self):
        with self.assertRaises(ValueError):
            evaluate("2 3 4")

    def test_101(self):
        with self.assertRaises(ValueError):
            evaluate("2 +")

    def test_102(self):
        self.assert_value("+ 5", 5, int)

    def test_103(self):
        with self.assertRaises(ValueError):
            evaluate("* 3")

    def test_104(self):
        with self.assertRaises(ValueError):
            evaluate("1 ** ")

    def test_105(self):
        with self.assertRaises(ValueError):
            evaluate("1 +* 2")

    def test_106(self):
        with self.assertRaises(ValueError):
            evaluate("2 ** * 3")

    def test_107(self):
        with self.assertRaises(ValueError):
            evaluate("%")

    def test_108(self):
        with self.assertRaises(ValueError):
            evaluate("3 %")

    def test_109(self):
        with self.assertRaises(ValueError):
            evaluate("/ 3")

    def test_110(self):
        with self.assertRaises(ValueError):
            evaluate("// 3")


# ---------------------------------------------------------------------------
# L. Whitespace variations / misc lexical
# ---------------------------------------------------------------------------
class TestWhitespaceVariations(ValueCasesMixin, unittest.TestCase):
    def test_111(self):
        self.assert_value("2  +  3", 5, int)

    def test_112(self):
        self.assert_value("2\t*\t3", 6, int)

    def test_113(self):
        self.assert_value("2\n+\n3", 5, int)

    def test_114(self):
        self.assert_value("(  1  +  2  )", 3, int)

    def test_115(self):
        self.assert_value("- - - - -5", -5, int)

    def test_116(self):
        self.assert_value("+-3", -3, int)


# ---------------------------------------------------------------------------
# M. Large numbers / unbounded-int, no artificial limits
# ---------------------------------------------------------------------------
class TestLargeNumbers(ValueCasesMixin, unittest.TestCase):
    def test_117(self):
        self.assert_value(
            "1000000000000000000000*2",
            2000000000000000000000,
            int,
        )

    def test_118(self):
        self.assert_value("2**100", 1267650600228229401496703205376, int)

    def test_119(self):
        digits = "9" * 50
        self.assert_value(digits, int(digits), int)

    def test_120_huge_exponent_is_fast_and_unbounded(self):
        result = evaluate("2**1000")
        self.assertIsInstance(result, int)
        self.assertEqual(result, 2 ** 1000)


# ---------------------------------------------------------------------------
# N. Non-string input to evaluate
# ---------------------------------------------------------------------------
class TestNonStringInput(unittest.TestCase):
    def test_121_none(self):
        with self.assertRaises(TypeError):
            evaluate(None)

    def test_122_int(self):
        with self.assertRaises(TypeError):
            evaluate(5)

    def test_123_bytes(self):
        with self.assertRaises(TypeError):
            evaluate(b"1+2")

    def test_124_list(self):
        with self.assertRaises(TypeError):
            evaluate([])


# ---------------------------------------------------------------------------
# Extra: deep nesting / recursion-depth robustness (spec item 7 / trap 9)
# ---------------------------------------------------------------------------
class TestDeepNesting(unittest.TestCase):
    def test_deep_parens_10000(self):
        n = 10000
        text = "(" * n + "1" + ")" * n
        self.assertEqual(evaluate(text), 1)

    def test_deep_unary_minus_10000_even(self):
        n = 10000  # even -> positive
        text = "-" * n + "5"
        self.assertEqual(evaluate(text), 5)

    def test_deep_unary_minus_10001_odd(self):
        n = 10001  # odd -> negative
        text = "-" * n + "5"
        self.assertEqual(evaluate(text), -5)

    def test_deep_nesting_does_not_raise_recursion_error(self):
        n = 10000
        text = "(" * n + "1" + ")" * n
        try:
            evaluate(text)
        except RecursionError:
            self.fail("evaluate() raised RecursionError for deep nesting")


# ---------------------------------------------------------------------------
# Extra: maximal-munch / stray-operator traps spelled out in the brief
# ---------------------------------------------------------------------------
class TestExtraTraps(ValueCasesMixin, unittest.TestCase):
    def test_zero_exponent_from_computed_zero_base(self):
        self.assert_value("(0-0)**0", 1, int)

    def test_negative_exponent_via_parenthesized_expression(self):
        with self.assertRaises(ValueError):
            evaluate("(8/2) ** -1")

    def test_int_division_exact_stays_float(self):
        result = evaluate("6/3")
        self.assertIsInstance(result, float)
        self.assertEqual(result, 2.0)

    def test_bool_never_produced(self):
        result = evaluate("1+1")
        self.assertNotIsInstance(result, bool)


def _run() -> bool:
    loader = unittest.TestLoader()
    suite = loader.loadTestsFromModule(sys.modules[__name__])
    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)
    total = result.testsRun
    failed = len(result.failures) + len(result.errors)
    passed = total - failed
    print("\n" + "=" * 70)
    print(f"SUMMARY: {passed}/{total} passed, {failed} failed")
    print("=" * 70)
    return result.wasSuccessful()


if __name__ == "__main__":
    success = _run()
    sys.exit(0 if success else 1)

